/* Generated by scripts/split-content.mjs — do not edit by hand.
   The glossary and a sample of the question bank. The rest is served
   from the content function once entitlement is confirmed. */
window.DATA = {"cards":[{"id":"c000","term":"Pod","def":"The smallest deployable unit in Kubernetes. Contains one or more containers sharing network and storage. Ephemeral by design.","cat":"Systems","sub":"CKA/CKAD"},{"id":"c001","term":"Deployment","def":"Declarative specification for Pods and ReplicaSets. Manages rolling updates, rollbacks, and scaling.","cat":"Systems","sub":"CKA/CKAD"},{"id":"c002","term":"ReplicaSet","def":"Ensures a specified number of identical Pods are running. Created and managed by Deployments; rarely used directly.","cat":"Systems","sub":"CKA/CKAD"},{"id":"c003","term":"Service (Kubernetes)","def":"Stable network endpoint for a set of Pods. Types: ClusterIP (internal), NodePort (external via node), LoadBalancer (cloud LB), ExternalName (DNS alias).","cat":"Systems","sub":"CKA/CKAD"},{"id":"c004","term":"Ingress","def":"API object managing external HTTP/HTTPS access to Services. Provides host/path routing, TLS termination, and name-based virtual hosting.","cat":"Systems","sub":"CKA/CKAD"},{"id":"c005","term":"ConfigMap / Secret","def":"ConfigMap stores non-sensitive configuration as key-value pairs. Secret stores sensitive data (base64-encoded, not encrypted by default).","cat":"Systems","sub":"CKA/CKAD"},{"id":"c006","term":"Namespace","def":"Virtual cluster within a physical cluster. Provides scope for names and resource quotas. Default, kube-system, and kube-public are built-in.","cat":"Systems","sub":"CKA/CKAD"},{"id":"c007","term":"PersistentVolume / PVC","def":"PV is a cluster storage resource. PVC is a user's request for storage. Dynamic provisioning creates PVs automatically from StorageClasses.","cat":"Systems","sub":"CKA/CKAD"},{"id":"c008","term":"StatefulSet","def":"Like a Deployment but for stateful applications. Provides stable network identity, ordered deployment/scaling, and persistent storage per Pod.","cat":"Systems","sub":"CKA/CKAD"},{"id":"c009","term":"DaemonSet","def":"Ensures a copy of a Pod runs on every (or selected) node. Used for log collectors, monitoring agents, and network plugins.","cat":"Systems","sub":"CKA/CKAD"},{"id":"c010","term":"Job / CronJob","def":"Job runs a Pod to completion. CronJob schedules Jobs on a cron schedule. Both handle batch and periodic workloads.","cat":"Systems","sub":"CKA/CKAD"},{"id":"c011","term":"kubectl","def":"Command-line tool for interacting with Kubernetes clusters. Applies manifests, inspects resources, streams logs, and executes into containers.","cat":"Systems","sub":"CKA/CKAD"},{"id":"c012","term":"etcd","def":"Distributed key-value store used as Kubernetes' backing store for all cluster data. Consistency and backup are critical for cluster recovery.","cat":"Systems","sub":"CKA/CKAD"},{"id":"c013","term":"Control Plane Components","def":"API server (front-end), etcd (state store), scheduler (assigns Pods to nodes), controller manager (maintains desired state).","cat":"Systems","sub":"CKA/CKAD"},{"id":"c014","term":"kubelet","def":"Agent running on every node. Ensures containers described in PodSpecs are running and healthy. Reports node status to the API server.","cat":"Systems","sub":"CKA/CKAD"},{"id":"c015","term":"kube-proxy","def":"Network proxy on each node implementing Service abstraction. Maintains iptables or IPVS rules for routing traffic to Pod endpoints.","cat":"Systems","sub":"CKA/CKAD"},{"id":"c016","term":"RBAC in Kubernetes","def":"Controls access to cluster resources via Roles/ClusterRoles (permissions) and RoleBindings/ClusterRoleBindings (assignment to subjects).","cat":"Systems","sub":"CKA/CKAD"},{"id":"c017","term":"NetworkPolicy","def":"Specifies how Pods are allowed to communicate. Default is all-allow; NetworkPolicies whitelist ingress and egress traffic by Pod label, namespace, or CIDR.","cat":"Systems","sub":"CKA/CKAD"},{"id":"c018","term":"Helm","def":"Package manager for Kubernetes. Charts are templated manifests. Enables versioned, repeatable deployments with configurable values.","cat":"Systems","sub":"CKA/CKAD"},{"id":"c019","term":"Resource Requests and Limits","def":"Requests guarantee minimum CPU/memory for scheduling. Limits cap maximum usage. The scheduler uses requests; the runtime enforces limits.","cat":"Systems","sub":"CKA/CKAD"},{"id":"c020","term":"Liveness / Readiness / Startup Probes","def":"Liveness: restart if unhealthy. Readiness: remove from Service endpoints if not ready. Startup: delay other probes until the app initializes.","cat":"Systems","sub":"CKA/CKAD"},{"id":"c021","term":"Horizontal Pod Autoscaler (HPA)","def":"Automatically scales the number of Pod replicas based on CPU/memory utilization or custom metrics.","cat":"Systems","sub":"CKA/CKAD"},{"id":"c022","term":"Terraform","def":"HashiCorp's Infrastructure as Code tool. Declarative HCL configuration, provider-agnostic, manages lifecycle of cloud and on-premises resources.","cat":"Systems","sub":"Terraform"},{"id":"c023","term":"Provider","def":"A plugin that Terraform uses to interact with a specific platform (AWS, Azure, GCP, Kubernetes, etc.). Each provider exposes resources and data sources.","cat":"Systems","sub":"Terraform"},{"id":"c024","term":"Resource","def":"A single infrastructure object Terraform manages (an EC2 instance, a DNS record, a Kubernetes deployment). Defined in HCL with a type and name.","cat":"Systems","sub":"Terraform"},{"id":"c025","term":"Data Source","def":"Reads information from an existing resource not managed by the current configuration. Used to reference infrastructure managed elsewhere.","cat":"Systems","sub":"Terraform"},{"id":"c026","term":"State File","def":"JSON file recording the current state of managed infrastructure. Maps configuration to real-world resources. Must be stored securely and backed up.","cat":"Systems","sub":"Terraform"},{"id":"c027","term":"Remote State Backend","def":"Stores state in a shared location (S3, GCS, Azure Blob, Terraform Cloud) for team collaboration. Supports locking to prevent concurrent modifications.","cat":"Systems","sub":"Terraform"},{"id":"c028","term":"Plan / Apply / Destroy","def":"Plan previews changes. Apply executes them. Destroy removes all managed resources. Plan output should always be reviewed before applying.","cat":"Systems","sub":"Terraform"},{"id":"c029","term":"Modules","def":"Reusable, self-contained packages of Terraform configuration. Accept inputs (variables), produce outputs. Published on the Terraform Registry or stored internally.","cat":"Systems","sub":"Terraform"},{"id":"c030","term":"Variables and Outputs","def":"Variables parameterize configurations (string, number, bool, list, map). Outputs expose values from a module for use elsewhere.","cat":"Systems","sub":"Terraform"},{"id":"c031","term":"terraform init","def":"Initializes a working directory, downloads providers and modules, and configures the backend. Must run before plan or apply.","cat":"Systems","sub":"Terraform"},{"id":"c032","term":"terraform fmt / validate","def":"fmt formats HCL files to canonical style. validate checks syntax and internal consistency without accessing providers.","cat":"Systems","sub":"Terraform"},{"id":"c033","term":"Provisioners","def":"Execute scripts on a resource after creation (local-exec, remote-exec). Considered a last resort — configuration management tools are preferred.","cat":"Systems","sub":"Terraform"},{"id":"c034","term":"Workspaces","def":"Isolated state environments within a single configuration. Useful for separating dev/staging/prod without duplicating code.","cat":"Systems","sub":"Terraform"},{"id":"c035","term":"Terraform Cloud / Enterprise","def":"SaaS/self-hosted platform adding remote execution, state management, policy as code (Sentinel), and team collaboration.","cat":"Systems","sub":"Terraform"},{"id":"c036","term":"Import","def":"Brings existing infrastructure under Terraform management by associating a real resource with a configuration block. State is updated, but code must be written manually.","cat":"Systems","sub":"Terraform"},{"id":"c037","term":"Linux Filesystem Hierarchy","def":"/bin (binaries), /etc (configuration), /home (users), /var (variable data), /tmp (temporary), /proc and /sys (kernel interfaces).","cat":"Systems","sub":"LFCE"},{"id":"c038","term":"systemd","def":"Init system and service manager for modern Linux. Units define services, timers, mounts, and targets. systemctl is the control command.","cat":"Systems","sub":"LFCE"},{"id":"c039","term":"journalctl","def":"Queries the systemd journal for logs. Supports filtering by unit, priority, time range, and boot session.","cat":"Systems","sub":"LFCE"},{"id":"c040","term":"Package Management","def":"apt/dpkg for Debian/Ubuntu, dnf/yum/rpm for RHEL/Fedora. Manages software installation, updates, dependencies, and removal.","cat":"Systems","sub":"LFCE"},{"id":"c041","term":"User and Group Management","def":"useradd, usermod, userdel, groupadd. /etc/passwd stores users, /etc/shadow stores hashed passwords, /etc/group stores groups.","cat":"Systems","sub":"LFCE"},{"id":"c042","term":"File Permissions","def":"Read (4), write (2), execute (1) for owner, group, others. chmod sets permissions, chown changes ownership. SUID, SGID, and sticky bit are special permissions.","cat":"Systems","sub":"LFCE"},{"id":"c043","term":"SELinux / AppArmor","def":"Mandatory Access Control frameworks. SELinux uses labels and policies (enforcing/permissive/disabled). AppArmor uses path-based profiles.","cat":"Systems","sub":"LFCE"},{"id":"c044","term":"iptables / nftables","def":"Linux packet filtering frameworks. Define rules for INPUT, OUTPUT, and FORWARD chains. nftables is the modern replacement with unified syntax.","cat":"Systems","sub":"LFCE"},{"id":"c045","term":"LVM (Logical Volume Manager)","def":"Abstraction layer over physical disks. Physical Volumes → Volume Groups → Logical Volumes. Enables dynamic resizing and snapshots.","cat":"Systems","sub":"LFCE"},{"id":"c046","term":"SSH Configuration","def":"sshd_config controls server behavior: key-based auth, PermitRootLogin, AllowUsers, port, and protocol settings. Key-based auth is preferred over passwords.","cat":"Systems","sub":"LFCE"},{"id":"c047","term":"cron / at","def":"cron schedules recurring tasks via crontab (minute, hour, day, month, weekday). at schedules one-time future tasks.","cat":"Systems","sub":"LFCE"},{"id":"c048","term":"Networking in Linux","def":"ip command manages interfaces, addresses, and routes. ss replaces netstat for socket statistics. /etc/resolv.conf for DNS. NetworkManager or systemd-networkd for management.","cat":"Systems","sub":"LFCE"},{"id":"c049","term":"Process Management","def":"ps, top, htop show processes. kill sends signals (SIGTERM, SIGKILL). nice/renice set priority. & backgrounds, nohup detaches from terminal.","cat":"Systems","sub":"LFCE"},{"id":"c050","term":"Shell Scripting","def":"Bash scripts automate tasks. Variables, conditionals (if/elif/else), loops (for/while), functions, exit codes, and piping are core constructs.","cat":"Systems","sub":"LFCE"},{"id":"c051","term":"RAID Levels","def":"RAID 0 (striping, no redundancy), RAID 1 (mirroring), RAID 5 (striping with parity, min 3 disks), RAID 6 (double parity), RAID 10 (mirror + stripe).","cat":"Systems","sub":"LFCE"},{"id":"c052","term":"Containers on Linux","def":"Built on namespaces (isolation), cgroups (resource limits), and overlay filesystems. Docker and Podman are common runtimes.","cat":"Systems","sub":"LFCE"}],"questions":[{"cat":"Systems","sub":"CKA/CKAD","stem":"A Pod that runs on every node in the cluster for log collection is managed by:","choices":["A StatefulSet","A DaemonSet","A Deployment","A CronJob"],"answer":1,"label":"DaemonSet","why":"DaemonSets ensure one Pod per node, making them ideal for node-level agents like log collectors and monitoring daemons.","id":"q001","n":1},{"cat":"Systems","sub":"CKA/CKAD","stem":"An application requires a stable network identity and persistent storage per replica. The correct workload type is:","choices":["Deployment","Job","StatefulSet","DaemonSet"],"answer":2,"label":"StatefulSet","why":"StatefulSets provide stable hostnames, ordered deployment, and persistent storage per Pod — requirements that Deployments don't meet.","id":"q002","n":2},{"cat":"Systems","sub":"CKA/CKAD","stem":"A Kubernetes Service of type ClusterIP is accessible:","choices":["From any IP on the internet","Only from within the cluster","From outside the cluster via a load balancer","Only from the node running the Pod"],"answer":1,"label":"ClusterIP scope","why":"ClusterIP is the default Service type and provides an internal-only cluster IP address. NodePort or LoadBalancer expose externally.","id":"q003","n":3},{"cat":"Systems","sub":"CKA/CKAD","stem":"The etcd component in a Kubernetes cluster stores:","choices":["Application logs","Container images","Prometheus metrics","All cluster state and configuration data"],"answer":3,"label":"etcd purpose","why":"etcd is the backing store for all Kubernetes data. Losing etcd without a backup means losing the cluster's entire desired state.","id":"q004","n":4},{"cat":"Systems","sub":"CKA/CKAD","stem":"A container that repeatedly crashes and is restarted by Kubernetes has a failing:","choices":["NetworkPolicy","Readiness probe","Startup probe","Liveness probe"],"answer":3,"label":"Liveness probe restart","why":"Liveness probes detect unhealthy containers and trigger restarts. Readiness probes only remove the Pod from Service endpoints.","id":"q005","n":5},{"cat":"Systems","sub":"CKA/CKAD","stem":"To restrict traffic so that only Pods with label app=frontend can reach Pods with label app=backend, you create:","choices":["A Service","A ResourceQuota","An Ingress rule","A NetworkPolicy"],"answer":3,"label":"NetworkPolicy","why":"NetworkPolicies control Pod-to-Pod communication using label selectors, providing microsegmentation within the cluster.","id":"q006","n":6},{"cat":"Systems","sub":"CKA/CKAD","stem":"In Kubernetes RBAC, a Role grants permissions within a single namespace, while a ClusterRole grants:","choices":["Permissions in a single namespace only","Read-only access only","Permissions cluster-wide or across all namespaces","Access to external resources only"],"answer":2,"label":"ClusterRole scope","why":"ClusterRoles can grant permissions across all namespaces and on cluster-scoped resources like nodes and PersistentVolumes.","id":"q007","n":7},{"cat":"Systems","sub":"CKA/CKAD","stem":"A Horizontal Pod Autoscaler scales based on:","choices":["The age of the Pods","The number of nodes in the cluster","The number of Services","Observed CPU/memory utilization or custom metrics"],"answer":3,"label":"HPA scaling basis","why":"HPA adjusts replica count based on observed metrics vs. target thresholds, most commonly CPU utilization.","id":"q008","n":8},{"cat":"Systems","sub":"CKA/CKAD","stem":"Helm is used in Kubernetes for:","choices":["Packaging, templating, and managing application deployments","Container image building","Storage provisioning","Network policy enforcement"],"answer":0,"label":"Helm purpose","why":"Helm charts are reusable packages of Kubernetes manifests with templating, enabling versioned, configurable deployments.","id":"q009","n":9},{"cat":"Systems","sub":"CKA/CKAD","stem":"The difference between a resource request and a limit in Kubernetes is:","choices":["Requests guarantee minimum resources for scheduling; limits cap maximum usage","Requests are ignored; only limits matter","They are interchangeable terms","Limits guarantee minimum resources; requests cap maximum"],"answer":0,"label":"Requests vs. limits","why":"The scheduler uses requests to find a suitable node. The runtime enforces limits to prevent a container from exceeding its allocation.","id":"q010","n":10}],"meta":{"total":24,"free":10,"split":true}};
